import { anthropic } from '@ai-sdk/anthropic'
import { defineAgent, defineTool } from 'dopus'
import { z } from 'zod'
import app, { locales } from './agent/prompts/app'
import preset from './agent/prompts/preset'
import { getExport, startExport } from './app/actions/exports'
import { cancelOrder, getCurrentUser, listMyOrders } from './app/actions/orders'
import { mockModel } from './lib/mock-model'
import { getSession } from './lib/session'

/**
 * Generated by `dopus init`, then edited: the tools below are the app's existing server actions.
 * They run inside the agent request, so they see the caller's session cookie and apply their own checks.
 * `identify` tells dopus who is signed in: anonymous users only get the tools marked `public`.
 */
export default defineAgent({
  // DOPUS_MOCK_MODEL=1 swaps in a scripted model for tests (no API key, no cost).
  model: process.env.DOPUS_MOCK_MODEL === '1' ? mockModel() : anthropic('claude-sonnet-5-5'),
  tools: {
    getCurrentUser: defineTool(() => getCurrentUser(), {
      description: 'Tells whether the user is signed in, and as whom.',
      usage: 'When the user asks who they are or whether they are signed in.',
      input: z.object({}),
      public: true,
    }),
    listMyOrders: defineTool(() => listMyOrders(), {
      description: "Lists the signed-in user's orders with id, item and status.",
      usage: 'When the user asks about their orders, or before cancelling one by description.',
      input: z.object({}),
    }),
    cancelOrder: defineTool((input) => cancelOrder(input.orderId), {
      description: 'Cancels one open order of the signed-in user.',
      usage: 'Only when the user explicitly asks to cancel a specific order.',
      input: z.object({ orderId: z.string().describe('Order id, e.g. "o-1"') }),
      confirm: true,
    }),
    // Background job: returns at once; the chat hears when it finishes (components/agent/agent.tsx).
    startExport: defineTool(() => startExport(), {
      description: "Starts exporting the user's orders to a CSV file.",
      usage: 'When the user asks for an export of their orders.',
      input: z.object({}),
      job: (result) => result.jobId,
    }),
    getExport: defineTool((input) => getExport(input.jobId), {
      description: 'Reads an export job: its status and, when done, the file.',
      usage: 'After the app says an export job has finished.',
      input: z.object({ jobId: z.string() }),
    }),
  },
  identify: async () => {
    const session = await getSession()
    return session ? { id: session.user } : undefined
  },
  prompt: { preset, app, locales },
})
